import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';
import{activeCases,activeFrame,comparisonCases,transportOutcome,bothEnergyStates}from './active-models.js?v=20261023-physicscomplete01';
import{activeFigure,transportFigure}from './active-figures.js?v=20261023-physicscomplete01';
const opts=(items,v)=>'<option value="">Choose…</option>'+items.map(([k,t])=>`<option value="${k}"${v===k?' selected':''}>${t}</option>`).join('');
export function showActive(id='root',w={}){const f=activeFrame(id,w.energy,w.step);renderCustomModel({name:f.name,formula:'Left '+f.left+' · Right '+f.right+' · '+(f.energy?'Energy available':'No energy supplied'),kicker:'SCHEMATIC MEMBRANE · ACTIVE ROUTE',atoms:[],bonds:[],radius:3,viewKey:'active-membrane',startPaused:true,note:'Symbolic uptake only · equal comparison volumes',aria:f.leftName+' '+f.left+' particles; '+f.rightName+' '+f.right+'. '+(f.energy?'Respiration energy available':'No energy supplied to active route')+'. Shapes and transport boundary are symbolic.',diagram:activeFigure(id,f.energy,f.step)+'<p class="diagram-caption">Only the selected active route is modelled. Without its energy supply, passive movement may still occur. Counts, membrane shapes and steps are illustrative; no molecular mechanism or energy-per-particle ratio is implied.</p>',build:(g,T)=>{const head=new T.SphereGeometry(.1,16,12),mat=new T.MeshStandardMaterial({color:0xb7c8d6,roughness:.4});for(let y=-1.4;y<1.5;y+=.35)for(let z=-.7;z<.8;z+=.35)for(const x of[-.18,.18]){const h=new T.Mesh(head,mat);h.position.set(x,y,z);g.add(h);}const gate=new T.Mesh(new T.TorusGeometry(.36,.12,16,40),new T.MeshStandardMaterial({color:f.energy?0xed8b78:0x526f86,roughness:.25,metalness:.12}));gate.rotation.y=Math.PI/2;g.add(gate);for(const[side,n]of[[-1,f.left],[1,f.right]])for(let i=0;i<n;i++){const particle=new T.Mesh(id==='gut'?new T.BoxGeometry(.17,.17,.17):new T.SphereGeometry(.095,20,16),new T.MeshStandardMaterial({color:0xed8b78,roughness:.24}));particle.position.set(side*(.85+(i%3)*.35),-1.15+Math.floor(i/3)*.45,Math.sin(i*2)*.45);g.add(particle);}}});}
export function showTransport(mode='diffusion',w={}){const c=w.case||comparisonCases.find(c=>c.process===mode)||comparisonCases[0];renderDiagram('Choose the transport process',c.title,transportFigure({...c,energy:w.energy,supported:w.supported,water:c.substance==='Water'})+'<p class="diagram-caption">Arrows show the requested net transfer. Concentrations use the same arbitrary units and equal comparison volumes; water cases label solute concentration. Shapes are symbolic, not a membrane mechanism or measured rate.</p>','SUBSTANCE · GRADIENT · ENERGY');}
export function mountActive(l,p,root,{save,done,feedback}){const w=p.widget,$=s=>root.querySelector(s),compare=l.widget==='transport-compare',total=compare?5:3;w.task??=0;w.passed??=[];w.records??={};const task=w.task%total,c=(compare?comparisonCases:activeCases)[task],r=w.records[c.id]??={energy:false,step:0,states:[],tested:[]};const tail='<button class="secondary" id="checkActive">Check reasoning</button><button class="secondary" id="nextActive">Next challenge →</button><p id="activeProgress">'+w.passed.length+' / '+total+' complete</p>';const finish=()=>{if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;save();done();}save();$('#activeProgress').textContent=w.passed.length+' / '+total+' complete';};
if(!compare){root.innerHTML=`<p><b>${task+1} / 3 · ${c.name}</b></p><p>${c.leftName} starts at${c.left}; ${c.rightName} at${c.right}, in equal comparison volumes. ${c.purpose}</p><label class="field-label" for="activeDirection">Predict the active uptake direction</label><select class="lab-select" id="activeDirection">${opts([['right','Left to right'],['left','Right to left'],['none','No uptake can ever occur']],r.direction)}</select><label class="field-label" for="activeEnergySource">Energy source for this uptake</label><select id="activeEnergySource" class="lab-select">${opts([['respiration','Respiration'],['gradient','Concentration difference alone'],['none','No energy is needed']],r.source)}</select><button class="secondary" id="toggleActiveEnergy">${r.energy?'Remove':'Supply'} respiration energy</button><button class="secondary" id="stepActive">Step transport →</button><p id="activeReadout" aria-live="polite"></p>`+tail;
const draw=()=>{const f=activeFrame(c.id,r.energy,r.step);showActive(c.id,r);$('#toggleActiveEnergy').textContent=(r.energy?'Remove':'Supply')+' respiration energy';$('#activeReadout').textContent='Step '+r.step+': left '+f.left+', right '+f.right+'. Active transfers: '+f.moved+'. '+(!r.energy?'No active uptake here; passive movement can continue.':'This route moves particles against the gradient.');};$('#activeDirection').onchange=e=>{r.direction=e.target.value;save();};$('#activeEnergySource').onchange=e=>{r.source=e.target.value;save();};$('#toggleActiveEnergy').onclick=()=>{r.energy=!r.energy;r.step=0;save();draw();};$('#stepActive').onclick=()=>{if(!r.direction||!r.source){feedback('Predict direction and energy source before running the model.',true);return;}r.step=Math.min(3,r.step+1);const state=r.energy?'on':'off';if(r.step===3&&!r.states.includes(state))r.states.push(state);save();draw();};$('#checkActive').onclick=()=>{if(!bothEnergyStates(r)){feedback('Run3 steps with energy supplied and3 without. Switching energy resets the same starting comparison.',true);return;}if(r.direction!==c.direction||r.source!=='respiration'){feedback('Active uptake is from dilute to concentrated, against the gradient. Energy comes from respiration; left/right is only the diagram layout.',true);return;}feedback(c.purpose+' The selected active route depends on respiration energy.');finish();};draw();
}else{root.innerHTML=`<p><b>${task+1} / 5 · ${c.title}</b></p><p>${c.substance==='Water'?'Solute concentration':c.substance+' concentration'}: ${c.leftName} ${c.left}; ${c.rightName} ${c.right}. Requested net transfer: ${c.direction==='right'?'left → right':'right → left'}.</p><label class="field-label" for="transportChoice">Choose a process to test</label><select id="transportChoice" class="lab-select">${opts([['diffusion','Diffusion'],['osmosis','Osmosis'],['active','Active transport']],r.process)}</select><button class="secondary" id="toggleActiveEnergy">${r.energy?'Remove':'Supply'} respiration energy</button><button class="secondary" id="testTransport">Test the route</button><p id="routeOutcome" aria-live="polite"></p><label class="field-label" for="transportReason">Explain the requested transfer</label><select id="transportReason" class="lab-select">${opts([['down','Particles down their gradient'],['water','Water across a partial membrane'],['against','Against gradient; energy needed']],r.reason)}</select>`+tail;
const draw=()=>{showTransport(c.process,{case:c,energy:r.energy,supported:r.supported});$('#toggleActiveEnergy').textContent=(r.energy?'Remove':'Supply')+' respiration energy';$('#routeOutcome').textContent=r.outcome||'Test a route and compare energy available/unavailable.';};$('#transportChoice').onchange=e=>{r.process=e.target.value;r.outcome='';r.supported=undefined;save();draw();};$('#transportReason').onchange=e=>{r.reason=e.target.value;save();};$('#toggleActiveEnergy').onclick=()=>{r.energy=!r.energy;r.outcome='';r.supported=undefined;save();draw();};$('#testTransport').onclick=()=>{if(!r.process){feedback('Choose the transport process first.',true);return;}const out=transportOutcome(c,r.process,r.energy);r.supported=out.moves;r.outcome=(out.moves?'Requested transfer supported. ':'Requested transfer not supported. ')+out.reason;const key=r.process+':'+(r.energy?'on':'off');if(!r.tested.includes(key))r.tested.push(key);save();draw();feedback(out.reason,!out.moves);};$('#checkActive').onclick=()=>{const reason={diffusion:'down',osmosis:'water',active:'against'}[c.process];if(r.process!==c.process||r.reason!==reason){feedback('Use the substance and gradient: osmosis is water through a partially permeable membrane; diffusion is down a gradient; active uptake is against it using respiration energy.',true);return;}if(!r.tested.includes(c.process+':on')||!r.tested.includes(c.process+':off')){feedback('Test the correct process with and without respiration energy, then explain whether its requested transfer depends on that supply.',true);return;}feedback(c.why);finish();};draw();}
$('#nextActive').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;save();feedback('');mountActive(l,p,root,{save,done,feedback});};}
